(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.BundleDuplicateLens=api})(typeof self!=='undefined'?self:this,function(){
  const clean=v=>String(v??'').trim();
  function parseRows(text){const lines=clean(text).split(/\r?\n/).map(clean).filter(Boolean);if(!lines.length)throw new Error('アセットを1行以上入力してね');return lines.map((line,index)=>{const cells=line.split(',').map(clean);if(cells.length!==3)throw new Error(`${index+1}行目: Bundle,Asset,Size KB の3列が必要`);const [bundle,asset,sizeRaw]=cells,sizeKB=Number(sizeRaw);if(!bundle||!asset)throw new Error(`${index+1}行目: BundleとAssetは必須`);if(!Number.isFinite(sizeKB)||sizeKB<=0||sizeKB>1e9)throw new Error(`${index+1}行目: Size KBは0より大きい数値にしてね`);return{bundle,asset,sizeKB,line:index+1}})}
  function analyze(rows,settings={}){const minSavingsKB=Number(settings.minSavingsKB??100);if(!Number.isFinite(minSavingsKB)||minSavingsKB<0||minSavingsKB>1e9)throw new Error('候補しきい値は0以上にしてね');const unique=new Map,assets=new Map,bundles=new Map;for(const row of rows){const pair=`${row.bundle}\u0000${row.asset}`;if(unique.has(pair))throw new Error(`${row.line}行目: 同じBundleとAssetが重複しているよ`);unique.set(pair,row);bundles.set(row.bundle,(bundles.get(row.bundle)||0)+row.sizeKB);if(!assets.has(row.asset))assets.set(row.asset,[]);assets.get(row.asset).push(row)}const totalKB=rows.reduce((s,x)=>s+x.sizeKB,0),duplicates=[];let duplicateKB=0;for(const [asset,uses] of assets){const bundleCount=uses.length;if(bundleCount<2)continue;const sizes=uses.map(x=>x.sizeKB),baseKB=Math.max(...sizes),currentKB=sizes.reduce((s,x)=>s+x,0),savingsKB=Math.max(0,currentKB-baseKB),sizeMismatch=Math.max(...sizes)!==Math.min(...sizes);duplicateKB+=savingsKB;duplicates.push({asset,bundles:uses.map(x=>x.bundle).sort(),bundleCount,currentKB,sharedKB:baseKB,savingsKB,sizeMismatch,action:savingsKB>=minSavingsKB?'shared候補':'小規模'})}duplicates.sort((a,b)=>b.savingsKB-a.savingsKB||a.asset.localeCompare(b.asset));const bundleRows=[...bundles].map(([bundle,sizeKB])=>({bundle,sizeKB,share:totalKB?sizeKB/totalKB*100:0})).sort((a,b)=>b.sizeKB-a.sizeKB);return{settings:{minSavingsKB},summary:{rowCount:rows.length,assetCount:assets.size,bundleCount:bundles.size,totalKB,duplicateAssetCount:duplicates.length,duplicateKB,duplicateRate:totalKB?duplicateKB/totalKB*100:0,optimizedKB:totalKB-duplicateKB,candidateCount:duplicates.filter(x=>x.savingsKB>=minSavingsKB).length},duplicates,bundles:bundleRows,status:duplicates.length?'duplicates':'clean'}}
  function exportData(result){return{generated_at:new Date().toISOString(),model:'bundle manifest duplication estimate',assumptions:['Each CSV row is one asset occurrence in one bundle','The largest listed size is retained when an asset moves to a shared bundle','Runtime loading, compression blocks, dependency topology and shared-bundle overhead are not simulated'],settings:result.settings,summary:result.summary,duplicates:result.duplicates,bundles:result.bundles}}
  return{parseRows,analyze,exportData};
});
